import{_ as s,a0 as n,w as l,s as m,ao as i,I as a,x as o,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const R=JSON.parse('{"title":"如何提升自动化的 ROI：4 个小提示 | LCTT x X-CMD","titleTemplate":false,"description":"如何提升自动化的 ROI：4 个小提示 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何提升自动化的 ROI：4 个小提示 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何提升自动化的 ROI：4 个小提示 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20171116 How to improve ROI on automation- 4 tips","title":"如何提升自动化的 ROI：4 个小提示","tag":"201807","desc":""},"relativePath":"201807/20171116 How to improve ROI on automation- 4 tips.md","filePath":"[post].md"}'),d={name:"201807/20171116 How to improve ROI on automation- 4 tips.md"};function O(u,t,C,f,T,I){const r=n("Link");return l(),m("div",null,[t[17]||(t[17]=i('<h1 id="如何提升自动化的-roi-4-个小提示" tabindex="-1">如何提升自动化的 ROI：4 个小提示 <a class="header-anchor" href="#如何提升自动化的-roi-4-个小提示" aria-label="Permalink to “如何提升自动化的 ROI：4 个小提示”">​</a></h1><blockquote><p>想要在你的自动化项目上达成强 RIO？采取如下步骤来规避失败。</p></blockquote><p><img src="https://enterprisersproject.com/sites/default/files/styles/620x350/public/cio_it_investments_2.png?itok=Ut1XIIBN" alt=""></p><p>在过去的几年间，有关自动化技术的讨论已经很多了。COO 们和运营团队（事实上还有其它的业务部门）对于可以重新定义成本随着工作量的增加而增加的这一事实而感到震惊。</p><p><ruby>机器人流程自动化<rt>Robotic Process Automation</rt></ruby>（RPA）似乎预示着运营的<ruby>圣杯<rt>Holy Grail</rt></ruby>：“我们提供了开箱即用的功能来满足你的日常操作所需 —— 检查电子邮件、保存附件、取数据、更新表格、生成报告、文件以及目录操作。构建一个机器人就像配置这些功能一样简单，然后用机器人将这些操作链接到一起，而不用去请求 IT 部门来构建它们。”这是一个多么诱人的话题。</p><p>低成本、几乎不出错、非常遵守流程 —— 对 COO 们和运营领导来说，这些好处真实可及。RPA 工具承诺，它从运营中节省下来的费用就足够支付它的成本（有一个短的回报期），这一事实使得业务的观点更具有吸引力。</p><p>自动化的谈论都趋向于类似的话题：COO 们和他们的团队想知道，自动化操作能够给他们带来什么好处。他们想知道 RPA 平台特性和功能，以及自动化在现实中的真实案例。从这一点到概念验证的实现过程通常很短暂。</p>',7)),a("p",null,[a("strong",null,[t[1]||(t[1]=o("[ 在实现人工智能技术方面的建议，可以查看我们相关的文章，",-1)),e(r,{href:"https://enterprisersproject.com/article/2017/11/crafting-your-ai-strategy-3-tips?sc_cid=70160000000h0aXAAQ"},{default:p(()=>[...t[0]||(t[0]=[o("制定你的人工智能策略：3 个小提示",-1)])]),_:1}),t[2]||(t[2]=o("]",-1))]),t[3]||(t[3]=o("。",-1))]),t[18]||(t[18]=i('<p>但是自动化带来的现实好处有时候可能比你所预期的时间要晚。采用 RPA 的公司在其实施后可能会对它们自身的 ROI 提出一些质疑。一些人没有看到预期之中的成本节省，并对其中的原因感到疑惑。</p><h3 id="你是不是自动化了错误的东西" tabindex="-1">你是不是自动化了错误的东西？ <a class="header-anchor" href="#你是不是自动化了错误的东西" aria-label="Permalink to “你是不是自动化了错误的东西？”">​</a></h3><p>在这些情况下，自动化的愿景和现实之间的差距是什么呢？我们来分析一下它，在决定去继续进行一个自动化验证项目（甚至是一个成熟的实践）之后，我们来看一下通常会发生什么。</p><p>在确定实施自动化所采用的路径之后，COO 一般会问运营领导和他的团队们，应该在哪个流程或者任务上实施自动化。虽然从原则上说应该鼓励他们参与进来，但是有时候这种方式产生的决策往往会产生一个次优选择。原因如下：</p><p>首先，团队领导经常会是“视野较窄”：他们对自己的流程和任务非常熟悉，但是对他们不参与的流程和任务并不是那么熟悉（特别是在他们没有太多运营经验的情况下）。这意味着他们在自己的工作领域内可能会找出比较适合自动化的候选者，但是在跨整个运营的其它领域中可能并不一定会找出最适合的。另外其它的像“我希望我的流程成为第一个实施自动化的候选者”这样的“软性”因素也会影响决定。</p><p>其次，候选流程的选择有时候会被自动化特性和能力的匹配度所支配，而不是根据自动化所带来的价值所决定的。一个常见的误解是，任何包括像电子邮件或目录监视、下载、计算等活动的任务都是自动化的最佳候选者。如果对这些任务实施自动化不能为组织产生价值，那么它们就不是正确的候选者。</p><p>那么，对于领导们来说，怎么才能确保实施自动化能够带来他们想要的 ROI 呢？实现这个目标有四步：</p><h3 id="_1-教育团队" tabindex="-1">1. 教育团队 <a class="header-anchor" href="#_1-教育团队" aria-label="Permalink to “1. 教育团队”">​</a></h3><p>在你的团队中，从 COO 职位以下的人中，很有可能都听说过 RPA 和运营自动化。同样很有可能他们都有许多的问题和担心。在你开始启动实施之前解决这些问题和担心是非常重要的。</p><p>对运营团队进行积极的教育可以大大地提升他们对自动化的热情和信心。培训主要关注于自动化和机器人是什么，它们在流程中一般扮演什么样的角色，哪个流程和任务最适合自动化，以及自动化的预期好处是什么。</p><p><strong>建议</strong>：邀请你的自动化合作伙伴去进行这些团队教育工作，你要有所控制：他们可能会非常乐意帮助你。在领导层将这些传播到更大范围的团队之前，你应该对他们的教育内容进行把关。</p><p>“实施自动化的第一步是更好地理解你的流程。”</p><h3 id="_2-审查内部流程" tabindex="-1">2. 审查内部流程 <a class="header-anchor" href="#_2-审查内部流程" aria-label="Permalink to “2. 审查内部流程”">​</a></h3><p>实施自动化的第一步是更好地理解你的流程。每个 RPA 实施之前都应该进行流程清单、动作分析、以及成本/价值的绘制练习。</p><p>这些练习对于理解流程中何处产生价值（或成本，如果没有价值的情况下）是至关重要的。并且这些练习需要在每个流程或者每个任务这样的粒度级别上来做。</p><p>这将有助你去识别和优先考虑最合适的自动化候选者。由于能够或者可能需要自动化的任务数量较多，流程一般需要分段实施自动化，因此优先级很重要。</p><p><strong>建议</strong>：设置一个小的工作团队，每个运营团队都参与其中。从每个运营团队中提名一个协调人 —— 一般是运营团队的领导或者团队管理者。在团队级别上组织一次研讨会，去构建流程清单、识别候选流程、以及推动购买。你的自动化合作伙伴很可能有“加速器” —— 调查问卷、计分卡等等 —— 这些将帮助你加速完成这项活动。</p><h3 id="_3-为优先业务提供强有力的指导" tabindex="-1">3. 为优先业务提供强有力的指导 <a class="header-anchor" href="#_3-为优先业务提供强有力的指导" aria-label="Permalink to “3. 为优先业务提供强有力的指导”">​</a></h3><p>实施自动化经常会涉及到在运营团队之间，基于业务价值对流程选择和自动化优先级上要达成共识（有时候是打破平衡）虽然团队的参与仍然是分析和实施的关键部分，但是领导仍然应该是最终的决策者。</p><p><strong>建议</strong>：安排定期会议从工作团队中获取最新信息。除了像推动达成共识和购买之外，工作团队还应该在团队层面上去查看领导们关于 ROI、平台选择、以及自动化优先级上的指导性决定。</p><h3 id="_4-应该推动-cio-和-coo-的紧密合作" tabindex="-1">4. 应该推动 CIO 和 COO 的紧密合作 <a class="header-anchor" href="#_4-应该推动-cio-和-coo-的紧密合作" aria-label="Permalink to “4. 应该推动 CIO 和 COO 的紧密合作”">​</a></h3><p>当运营团队和技术团队紧密合作时，自动化的实施将异常顺利。COO 需要去帮助推动与 CIO 团队的合作。</p><p>COO 和其他运营领导人的参与和监督对成功实施自动化是至关重要的。</p><p><strong>建议</strong>：COO 和 CIO 团队应该与第三方的自动化合作伙伴共同设立一个联合工作组（一个“战场”）。对每个参与者的责任进行明确的界定并持续跟踪。理想情况下，COO 和 CIO 应该至少有一个投入到联合工作组中，至少在初始发布中应该是这样。</p><p>自动化可以为组织创造重要的价值。然而为了在自动化中获得最优的投资回报，CIO 们必须在“入坑”之前做好规划。</p><hr>',26)),a("p",null,[t[5]||(t[5]=o("via: ",-1)),e(r,{href:"https://enterprisersproject.com/article/2017/11/how-improve-roi-automation-4-tips"},{default:p(()=>[...t[4]||(t[4]=[o("https://enterprisersproject.com/article/2017/11/how-improve-roi-automation-4-tips",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=o("作者：",-1)),e(r,{href:"https://enterprisersproject.com/user/rajesh-kamath"},{default:p(()=>[...t[6]||(t[6]=[o("Rajesh Kamath",-1)])]),_:1}),t[10]||(t[10]=o(" 译者：",-1)),e(r,{href:"https://github.com/qhwdw"},{default:p(()=>[...t[7]||(t[7]=[o("qhwdw",-1)])]),_:1}),t[11]||(t[11]=o(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[14]||(t[14]=o("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[12]||(t[12]=[o("LCTT",-1)])]),_:1}),t[15]||(t[15]=o(" 原创编译，",-1)),e(r,{href:"https://linux.cn/"},{default:p(()=>[...t[13]||(t[13]=[o("Linux中国",-1)])]),_:1}),t[16]||(t[16]=o(" 荣誉推出",-1))])])}const b=s(d,[["render",O]]);export{R as __pageData,b as default};
